#' Plot Simulated Posterior Phenology Curve
#'
#' Plots the posterior mean probability density curve and 95% Credible Interval
#' ribbon from a simulated posterior density matrix produced by [simulate_posterior_density()].
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior density curves generated by [simulate_posterior_density()].
#' @param log Logical, whether to plot probability density on a log10 scale (default = `TRUE`).
#' @param add Logical, whether to return `ggplot2` layers to add to an existing plot (default = `FALSE`).
#' @param color Character, hex color code for the line and ribbon (default = `"#d73027"`).
#' @return A `ggplot` object (if `add = FALSE`) or a list of `ggplot2` layers (if `add = TRUE`).
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' sim <- simulate_posterior_density(mod, create_newdata(mod), n_sims = 100, warnings = FALSE)
#' p <- plot_phenology_curve(sim, log = FALSE)
#' @export
plot_phenology_curve <- function(sim_mat, log = TRUE, add = FALSE, color = "#d73027") {
  grid <- get_doy_grid(sim_mat)
  df_plot <- data.frame(
    Yday = grid$doy,
    Density = rowMeans(sim_mat),
    Lower = apply(sim_mat, 1, stats::quantile, probs = 0.025),
    Upper = apply(sim_mat, 1, stats::quantile, probs = 0.975)
  )

  if (log) {
    df_plot[["Density"]] <- df_plot[["Density"]] + 1e-5
    df_plot[["Lower"]] <- pmax(df_plot[["Lower"]], 0) + 1e-5
    df_plot[["Upper"]] <- df_plot[["Upper"]] + 1e-5
  }

  layer_ribbon <- ggplot2::geom_ribbon(
    data = df_plot,
    ggplot2::aes(x = Yday, ymin = Lower, ymax = Upper),
    fill = color, alpha = 0.2, inherit.aes = FALSE
  )
  layer_line <- ggplot2::geom_line(
    data = df_plot,
    ggplot2::aes(x = Yday, y = Density),
    color = color, linewidth = 1, inherit.aes = FALSE
  )

  if (add) {
    return(list(layer_ribbon, layer_line))
  } else {
    p <- ggplot2::ggplot() +
      layer_ribbon +
      layer_line +
      ggplot2::theme_classic() +
      ggplot2::labs(
        x = "Day of Year",
        y = if (log) "Probability Density (log10)" else "Probability Density"
      )
    if (log) {
      p <- p + ggplot2::scale_y_log10(
        breaks = c(1e-4, 1e-3, 1e-2, 1e-1),
        labels = c("0.0001", "0.001", "0.01", "0.1")
      )
    }
    return(p)
  }
}
